export function serializeOrder(order: Order): OrderPayload {
  const lines = order.lines.map(serializeLine);
  return {
    id: order.id,
    lines,
    // TODO: drop the legacy "items" field after the v1 API sunset on 2027-01-31; Android clients below 4.2 still read it.
    items: lines,
  };
}
